require_once __DIR__ . '/../config/auth.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'settings');if($action==='password'){$current=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');$stmt=db()->prepare('SELECT password_hash FROM admins WHERE id=?');$stmt->execute([$_SESSION['admin_id']]);$hash=$stmt->fetchColumn();if(!password_verify($current,$hash)||strlen($new)<12||$new!==$confirm){flash('error','Current password did not match, or the new passwords are invalid. Use at least 12 characters.');}else{db()->prepare('UPDATE admins SET password_hash=?,force_password_change=0 WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),$_SESSION['admin_id']]);flash('success','Password changed.');}redirect('admin/settings.php');}else{if(($_SESSION['admin_role']??'')!=='Super Admin'){http_response_code(403);require __DIR__.'/../403.php';exit;}foreach(['phone','email','address','stat_courses','stat_departments','smtp_host','smtp_port','smtp_username','smtp_encryption','smtp_from_email','smtp_from_name','elearning_url'] as $key){$value=trim((string)($_POST[$key]??''));if($key==='email'&&$value!==''&&!filter_var($value,FILTER_VALIDATE_EMAIL))continue;db()->prepare('INSERT INTO settings (setting_key,setting_value) VALUES (?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$key,$value]);}flash('success','College and mail transport settings saved. Set TTVC_SMTP_PASS in the server environment for the mail password.');redirect('admin/settings.php');}}
