?><section class="admin-shell"><aside class="admin-sidebar"><?php foreach($nav as $label=>$path):?><a href="<?= e(url('admin/'.$path)) ?>"><?= e($label) ?></a><?php endforeach;?></aside><div class="admin-content"><p class="eyebrow">Administration</p><h1>Settings</h1><?php include __DIR__.'/../includes/alerts.php';?><?php if($force):?><div class="alert">Change the temporary password before using the admin dashboard.</div><?php endif;?><form class="form-panel" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="password"><h2>Change password</h2><div class="form-grid"><div class="field"><label>Current password</label><input name="current_password" type="password" required autocomplete="current-password"></div><div class="field"><label>New password (12+ characters)</label><input name="new_password" type="password" required minlength="12" autocomplete="new-password"></div><div class="field"><label>Confirm new password</label><input name="confirm_password" type="password" required minlength="12" autocomplete="new-password"></div></div><div class="form-actions"><button class="button">Update password</button></div></form><?php if(($_SESSION['admin_role']??'')==='Super Admin'):?><form class="form-panel" method="post" style="margin-top:22px"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="settings"><h2>College and email settings</h2><div class="form-grid"><?php foreach(['phone'=>'Phone','email'=>'Email','address'=>'Physical address','stat_courses'=>'Courses statistic','stat_departments'=>'Departments statistic','smtp_host'=>'SMTP host','smtp_port'=>'SMTP port','smtp_username'=>'SMTP username','smtp_encryption'=>'SMTP encryption','smtp_from_email'=>'Sender email','smtp_from_name'=>'Sender name','elearning_url'=>'E-learning URL'] as $key=>$label):?><div class="field"><label><?= e($label) ?></label><input name="<?= e($key) ?>" value="<?= e(setting($key)) ?>" <?= $key==='email'||$key==='smtp_from_email'?'type="email"':($key==='elearning_url'?'type="url"':'') ?>></div><?php endforeach;?></div><p class="body-copy">SMTP password is not stored in the database. Configure the TTVC_SMTP_PASS environment variable on your server.</p><div class="form-actions"><button class="button">Save settings</button><a class="button button-outline" href="<?= e(url('admin/users.php')) ?>">Manage administrators</a></div></form><?php endif;?></div></section><?php include __DIR__.'/../includes/footer.php';?>